TLM.f("Tempora/Pent01-4",{"officium":"Festum Sanctissimi Corporis Christi cum Octava privilegiata II ordinis","rule":["Gloria","Credo","Prefatio=Communis","Sequentia"],"ruleInherited":["Gloria","Credo","Prefatio=Trinitate"],"fallback":"Tempora/Pent01-0r","from":{"Commemoratio Oratio":"Tempora/Pent01-0r","Commemoratio Secreta":"Tempora/Pent01-0r","Commemoratio Postcommunio":"Tempora/Pent01-0r"},"sections":{"Introitus":[{"k":"ref","la":"Ps 80:17"},{"k":"text","la":"Cibávit eos ex ádipe fruménti, allelúja: et de petra, melle saturávit eos, allelúja, allelúja, allelúja."},{"k":"ref","la":"Ps 80:2"},{"k":"text","la":"Exsultáte Deo, adjutóri nostro: jubiláte Deo Jacob."},{"k":"macro","name":"Gloria"},{"k":"text","la":"Cibávit eos ex ádipe fruménti, allelúja: et de petra, melle saturávit eos, allelúja, allelúja, allelúja."}],"Oratio":[{"k":"text","la":"Deus, qui nobis sub Sacraménto mirábili passiónis tuæ memóriam reliquísti: tríbue, quǽsumus, ita nos Córporis et Sánguinis tui sacra mystéria venerári; ut redemptiónis tuæ fructum in nobis júgiter sentiámus:"},{"k":"macro","name":"Qui vivis"}],"Lectio":[{"k":"text","la":"Léctio Epistolæ beáti Pauli Apóstoli ad Corinthios"},{"k":"ref","la":"1 Cor 11:23-29"},{"k":"text","la":"Fratres: Ego enim accépi a Dómino quod et trádidi vobis, quóniam Dóminus Jesus, in qua nocte tradebátur, accépit panem, et grátias agens fregit, et dixit: Accípite, et manducáte: hoc est corpus meum, quod pro vobis tradétur: hoc fácite in meam commemoratiónem. Simíliter et cálicem, postquam cenávit, dicens: Hic calix novum Testaméntum est in meo sánguine. Hoc fácite, quotiescúmque bibétis, in meam commemoratiónem. Quotiescúmque enim manducábitis panem hunc et cálicem bibétis, mortem Dómini annuntiábitis, donec véniat. Itaque quicúmque manducáverit panem hunc vel bíberit cálicem Dómini indígne, reus erit córporis et sánguinis Dómini. Probet autem seípsum homo: et sic de pane illo edat et de calice bibat. Qui enim mandúcat et bibit indígne, judícium sibi mandúcat et bibit: non dijúdicans corpus Dómini."}],"Graduale":[{"k":"ref","la":"Ps 144:15-16"},{"k":"text","la":"Oculi ómnium in te sperant, Dómine: et tu das illis escam in témpore opportúno,"},{"k":"text","la":"Aperis tu manum tuam: et imples omne animal benedictióne. Allelúja, allelúja,","mark":"V"},{"k":"ref","la":"Joannes 6:56-57"},{"k":"text","la":"Caro mea vere est cibus, et sanguis meus vere est potus: qui mandúcat meam carnem et bibit meum sánguinem, in me manet et ego in eo. Alleluia."}],"Sequentia":[{"k":"rubric","la":"Thomæ de Aquino. (infra octavam ad libitum Celebrantis omitti potest, juxta Rubricas.)"},{"k":"text","la":"Lauda, Sion, Salvatórem,"},{"k":"text","la":"lauda ducem et pastórem"},{"k":"text","la":"in hymnis et cánticis."},{"k":"sep"},{"k":"text","la":"Quantum potes, tantum aude:"},{"k":"text","la":"quia major omni laude,"},{"k":"text","la":"nec laudáre súfficis."},{"k":"sep"},{"k":"text","la":"Laudis thema speciális,"},{"k":"text","la":"panis vivus et vitális"},{"k":"text","la":"hódie propónitur."},{"k":"sep"},{"k":"text","la":"Quem in sacræ mensa cenæ"},{"k":"text","la":"turbæ fratrum duodénæ"},{"k":"text","la":"datum non ambígitur."},{"k":"sep"},{"k":"text","la":"Sit laus plena, sit sonóra,"},{"k":"text","la":"sit jucúnda, sit decóra"},{"k":"text","la":"mentis jubilátio."},{"k":"sep"},{"k":"text","la":"Dies enim sollémnis agitur,"},{"k":"text","la":"in qua mensæ prima recólitur"},{"k":"text","la":"hujus institútio."},{"k":"sep"},{"k":"text","la":"In hac mensa novi Regis,"},{"k":"text","la":"novum Pascha novæ legis"},{"k":"text","la":"Phase vetus términat."},{"k":"sep"},{"k":"text","la":"Vetustátem nóvitas,"},{"k":"text","la":"umbram fugat véritas,"},{"k":"text","la":"noctem lux elíminat."},{"k":"sep"},{"k":"text","la":"Quod in cœna Christus gessit,"},{"k":"text","la":"faciéndum hoc expréssit"},{"k":"text","la":"in sui memóriam."},{"k":"sep"},{"k":"text","la":"Docti sacris institútis,"},{"k":"text","la":"panem, vinum in salútis"},{"k":"text","la":"consecrámus hóstiam."},{"k":"sep"},{"k":"text","la":"Dogma datur Christiánis,"},{"k":"text","la":"quod in carnem transit panis"},{"k":"text","la":"et vinum in sánguinem."},{"k":"sep"},{"k":"text","la":"Quod non capis, quod non vides,"},{"k":"text","la":"animosa fírmat fides,"},{"k":"text","la":"præter rerum órdinem."},{"k":"sep"},{"k":"text","la":"Sub divérsis speciébus,"},{"k":"text","la":"signis tantum, et non rebus,"},{"k":"text","la":"latent res exímiæ."},{"k":"sep"},{"k":"text","la":"Caro cibus, sanguis potus:"},{"k":"text","la":"manet tamen Christus totus"},{"k":"text","la":"sub utráque spécie."},{"k":"sep"},{"k":"text","la":"A suménte non concísus,"},{"k":"text","la":"non confráctus, non divísus:"},{"k":"text","la":"ínteger accípitur."},{"k":"sep"},{"k":"text","la":"Sumit unus, sumunt mille:"},{"k":"text","la":"quantum isti, tantum ille:"},{"k":"text","la":"nec sumptus consúmitur."},{"k":"sep"},{"k":"text","la":"Sumunt boni, sumunt mali"},{"k":"text","la":"sorte tamen inæquáli,"},{"k":"text","la":"vitæ vel intéritus."},{"k":"sep"},{"k":"text","la":"Mors est malis, vita bonis:"},{"k":"text","la":"vide, paris sumptiónis"},{"k":"text","la":"quam sit dispar éxitus."},{"k":"sep"},{"k":"text","la":"Fracto demum sacraménto,"},{"k":"text","la":"ne vacílles, sed meménto,"},{"k":"text","la":"tantum esse sub fragménto,"},{"k":"text","la":"quantum toto tégitur."},{"k":"sep"},{"k":"text","la":"Nulla rei fit scissúra:"},{"k":"text","la":"signi tantum fit fractúra:"},{"k":"text","la":"qua nec status nec statúra"},{"k":"text","la":"signáti minúitur."},{"k":"sep"},{"k":"text","la":"Ecce panis Angelórum,"},{"k":"text","la":"factus cibus viatórum:"},{"k":"text","la":"vere panis filiórum,"},{"k":"text","la":"non mitténdus cánibus."},{"k":"sep"},{"k":"text","la":"In figúris præsignátur,"},{"k":"text","la":"cum Isaac immolátur:"},{"k":"text","la":"agnus paschæ deputátur:"},{"k":"text","la":"datur manna pátribus."},{"k":"sep"},{"k":"text","la":"Bone pastor, panis vere,"},{"k":"text","la":"Jesu, nostri miserére:"},{"k":"text","la":"tu nos pasce, nos tuére:"},{"k":"text","la":"tu nos bona fac vidére"},{"k":"text","la":"in terra vivéntium."},{"k":"sep"},{"k":"text","la":"Tu, qui cuncta scis et vales:"},{"k":"text","la":"qui nos pascis hic mortáles:"},{"k":"text","la":"tuos ibi commensáles,"},{"k":"text","la":"coherédes et sodáles"},{"k":"text","la":"fac sanctórum cívium."},{"k":"text","la":"Amen. Allelúja."}],"Evangelium":[{"k":"text","la":"Sequéntia sancti Evangéli secúndum Joánnem."},{"k":"ref","la":"Joann 6:56-59"},{"k":"text","la":"In illo témpore: Dixit Jesus turbis Judæórum: Caro mea vere est cibus et sanguis meus vere est potus. Qui mandúcat meam carnem et bibit meum sánguinem, in me manet et ego in illo. Sicut misit me vivens Pater, et ego vivo propter Patrem: et qui mandúcat me, et ipse vivet propter me. Hic est panis, qui de cœlo descéndit. Non sicut manducavérunt patres vestri manna, et mórtui sunt. Qui mandúcat hunc panem, vivet in ætérnum."}],"Offertorium":[{"k":"ref","la":"Levit 21:6"},{"k":"text","la":"Sacerdótes Dómini incénsum et panes ófferunt Deo: et ideo sancti erunt Deo suo, et non pólluent nomen ejus, allelúja."}],"Secreta":[{"k":"text","la":"Ecclésiæ tuæ, quǽsumus, Dómine, unitátis et pacis propítius dona concéde: quæ sub oblátis munéribus mýstice designántur."},{"k":"macro","name":"Per Dominum"}],"Communio":[{"k":"ref","la":"1 Cor 11:26-27"},{"k":"text","la":"Quotiescúmque manducábitis panem hunc et cálicem bibétis, mortem Dómini annuntiábitis, donec véniat: itaque quicúmque manducáverit panem vel bíberit calicem Dómini indígne, reus erit córporis et sánguinis Dómini, allelúja."}],"Postcommunio":[{"k":"text","la":"Fac nos, quǽsumus, Dómine, divinitátis tuæ sempitérna fruitióne repléri: quam pretiósi Corporis et Sanguinis tui temporalis percéptio præfigúrat:"},{"k":"macro","name":"Qui vivis"}],"Commemoratio Oratio":[{"k":"rubric","la":"Pro Dominicam I post Pentecosten"},{"k":"text","la":"Deus, in te sperántium fortitúdo, adésto propítius invocatiónibus nostris: et, quia sine te nihil potest mortális infírmitas, præsta auxílium grátiæ tuæ; ut, in exsequéndis mandátis tuis, et voluntáte tibi et actióne placeámus."},{"k":"macro","name":"Per Dominum"}],"Commemoratio Secreta":[{"k":"rubric","la":"Pro Dominica"},{"k":"text","la":"Hóstias nostras, quǽsumus, Dómine, tibi dicátas placátus assúme: et ad perpétuum nobis tríbue proveníre subsídium."},{"k":"macro","name":"Per Dominum"}],"Commemoratio Postcommunio":[{"k":"rubric","la":"Pro Dominica"},{"k":"text","la":"Tantis, Dómine, repléti munéribus: præsta, quǽsumus; ut et salutária dona capiámus, et a tua numquam laude cessémus."},{"k":"macro","name":"Per Dominum"}]},"hr":{"5fda07c32f91a141":{"t":"Ps 80, 17, Ps 80, 2\n(Ps 80, 17) Nahranio ih je najboljom pšenicom, <i>aleluja</i>,\ni nasitio ih je medom iz pećine, <i>aleluja</i>, <i>aleluja</i>, <i>aleluja</i>.\n(Ps 80, 2) Kličite Bogu, našem pomagaču, veličajte Boga Jakovljeva.\n<i>Slava Ocu, i Sinu, i Duhu Svetomu. Kako bijaše na početku, tako i sada i vazda i u vijeke vjekova. Amen</i>.\n(Ps 80, 17) Nahranio ih je najboljom pšenicom, <i>aleluja</i>,\ni nasitio ih je medom iz pećine, <i>aleluja</i>, <i>aleluja</i>, <i>aleluja</i>.","kn":"(Ps. 80, 11). Nahranio ih je pšeničnom srži, aleluja, i medom dz stijene nasitio ih je, aleluja, aleluja. (Ps. 80, 2) Radujte se Bogu, pomoćniku našemu, kličite Bogu Jakovljevu. Slava Ocu . . . Nahranio ih je . . .","knRef":"Kniewald 1942, str. 344–345 (snimka 173) (OCR)"},"e139b8bc54cd1fbd":{"t":"<i>Pomolimo se</i>.\nBože, koji si nam u divnom sakramentu ostavio uspomenu svoje muke, podaj nam, molimo, tako častiti sveta otajstva tvoga tijela i krvi, da vazda osjećamo u sebi plod tvojeg otkupljenja:\n<i>koji živiš i kraljuješ s Bogom Ocem u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>.","kn":"Bože, koji si nam pod Sakramentom čudesnim uspomenu muke svoje ostavio; daj nam molimo, tako štovati sveta otajstva Tijela i Krvi Tvoje: da plod otkupljenja Tvojega vazda u sebi osjećamo. Koji živiš i kraljuješ.","knRef":"Kniewald 1942, str. 364–365 (snimka 183) (OCR)"},"bf4629a7fedf4663":{"t":"1 Kor 11, 23-29\nČitanje Poslanice bl. Pavla apostola Korinćanima. Braćo, ja sam od Gospodina primio što sam predao vama. Gospodin Isus one noći, kad je bio izdan, uze kruh, zahvali, prelomi i reče: Uzmite i jedite: Ovo je moje tijelo koje će se za vas predati. Ovo činite na moju uspomenu! Tako isto poslije večere uze čašu i reče: Ova je čaša novi zavjet u mojoj krvi. Tako svaki put, kad jedete ovaj kruh i pijete iz ove čaše, navješćujte smrt Gospodnju, dok on ne dođe. Zato će svaki koji bude nedostojno jeo ovaj kruh ili pio iz Gospodnje čaše biti krivac tijela i krvi Gospodnje. Stoga neka svatko ispita samog sebe i onda istom neka jede od kruha i pije iz čaše. Tko nedostojno jede i pije, na svoju osudu jede i pije, što ne razlikuje tijela Gospodnjega.","kn":"Čitanje poslanice bi. Pavla apostola Korinćaniina (I, 11, 23-29). Braćo! Ja sam od Gospodina primio, što sam vam predao: Gospodin Isus one noći, kad je bio izdan, uze kruh, zahvaljujući prelomi i reče: Uzmite i jedite, ovo je moje tijelo, koje će se predati za vas. Ovo činite na moju uspomenu. Tako i kalež po večeri reče: Ovaj kalez je Novi Zavjet u mojoj krvi; kadgod budete jeli ovaj kruh i pili ovaj kalež, navještat ćete Gospodnju smrt, dok ne dođe. Zato, tkogod bude jeo ovaj kruh ili pio Gospodnji kalež nedostojno, bit će krivac tijela i krvi Gospodnje. Neka se zato svaki čovjek ispita, i onda neka jede ovaj kruh i pije kalež. Jer tko jede i pije nedostojno, jede i pije sebi osudu, što ne razlikuje tijela Gospodnjega.","knRef":"Kniewald 1942, str. 364–365 (snimka 183) (OCR)"},"d29d2b7ff852f066":{"t":"Ps 144, 15-16\nOči sviju uzdaju se u tebe, Gospodine, i ti im daješ hranu u pravo vrijeme. Otvaraš svoju ruku i napunjaš blagoslovom sve što živi.\n\nIv 6, 56-57\n<i>Aleluja</i>, <i>aleluja</i>.\nMoje je tijelo zaista jelo i moja je krv zaista piće. Tko jede moje tijelo i pije moju krv, ostaje u meni i ja u njemu.","v":"∅ → aleluia","kn":"(Ps. 144, 15, 16). K Tebi smo, Gospodine, svi uzdigli oči svoje i Ti nam daješ hranu na vrijeme; otvaraš svoju ruku i napunjaš blagoslovom sve, što živi. Aleluja, aleluja. (Iv. 6, .50, 57). Tijelo je moje doista jelo i krv je moja doista piče; tko blaguje moje tijelo i pije moju krv, ostaje u meni i ja u njemu.","knRef":"Kniewald 1942, str. 364–365 (snimka 183) (OCR)"},"1f78b7b74b484713":{"t":"Hvali, Sion Spasitelja,/Vođu svog i učitelja/Pjesmama i popijevkom. <i>\n</i>\nUzdiži ga iznad svega,/Nećeš preveć hvalit njega/Niti kojom pohvalom. <i>\n</i>\nSlava evo velika je:/Živi kruh što život daje/Častit nam je ovaj dan. <i>\n</i>\nKruh što bi kod svetog stola/Među dvanaest apostola/Podijeljen i blagovan. <i>\n</i>\nPojmo punom, jasnom riječi,/Neka milo klikće, ječi,/Srdaca nam skladan glas. <i>\n</i>\nBlagdan slavni svetkujemo,/Ustanovu spominjemo/Gozbe što je dade Spas. <i>\n</i>\nNovog Kralja stol je ovo, /Na njem evo Janje novo, /Starom Vazmu dođe kraj. <i>\n</i>\nNesta slika toga trena,/Ispred zbilje minu sjena,/Tminu progna sunčev sjaj. <i>\n</i>\nŠto sam stvori ono veče,/Krist to isto tvorit reče, /Dovijeka na spomen svoj. <i>\n</i>\nPoučeni kako treba/Prinosimo dare neba/U žrtvi spasonosnoj. <i>\n</i>\nNauke nam svete glase: /Kruh u tijelo pretvara se, /Vino u krv Gospodnju. <i>\n</i>\nNe shvaćamo, ne gledamo,/Al' po jakoj vjeri znamo/Što van reda biva tu. <i>\n</i>\nU dva lika tu se taje/Silne stvari kojima je/Tek vanjština razlikom. <i>\n</i>\nTijelo hrana, krv je piće, /Kristovo je ipak biće /Sve pod svakom prilikom. <i>\n</i>\nKad ga primaš, nije dio, /Nije kriška nego cio /Ljudima se predaje. <i>\n</i>\nJeo jedan, jelo trista, /Svaki prima svega Krista, /Nit' ga jelom nestaje. <i>\n</i>\nDobar, opak, blaguju ga. /Kob je ipak svakom druga:/Život ili smrtni mrak. <i>\n</i>\nSmrt je zlima, dobrim žiće, /Gledaj: isti kruh i piće, /Plod toliko nejednak. <i>\n</i>\nKad je tajna razlomljena,/Znaj da čest joj odijeljena /Ko cjelina vrijedi njena,/Jer u svakoj sav je dar. <i>\n</i>\nNit se mijenja što pri tome /Stas ili stanje sakritome: /Prilike se samo lome/Ne trga se sama stvar. <i>\n</i>\nAnđeoske eto hrane, /Putnici se njome hrane. /To je kruh za odabrane, /Ne daje se svijetu zlom. <i>\n</i>\nDavno mu je spominjanje; /Izakovo žrtvovanje, /Izraelskog Vazma janje, /Mana, hrana pustinjom. <i>\n</i>\nDobar pastir, pravo jelo, /Smiluj nam se, Janje bijelo, /Daj nam hranu, svoje tijelo! /Brani, vodi stado cijelo /K strani žića blaženog. <i>\n</i>\nSilni Bože, što nam jesti/Na zemaljskoj daješ cesti/Daj nam ondje s tobom sjesti,/Među svece ti nas smjesti/U nebu kod stola svog. <i>\n</i>\n<i>amen</i>, <i>allelúia</i>."},"fe40eb3ec8fbc900":{"t":"Iv 6, 56-59\nSlijedi sveto Evanđelje po Ivanu. U ono vrijeme reče Isus mnoštvu Židova: Moje je tijelo zaista jelo i moja je krv zaista piće. Tko jede moje tijelo i pije moju krv, ostaje u meni i ja u njemu. Kao što je mene poslao živi Otac te ja živim od Oca, tako i tko jede mene,živjet će od mene. Ovo je kruh koji je sišao s neba. Nije on kao mana koju su jeli vaši oci, pa su isto umrli. Tko jede ovaj kruh, živjet će uvijek.","kn":"t Slijedi sveto evanđelje po Ivanu (6, 56-59). U ono vrijeme reče Isus židovskomu narodu: Moje je tijelo zaista jelo, i moja je krv zaista piće. Tko jede moje tijelo i pije moju krv, ostaje u meni i ja ti njemu. Kao što je mene poslao živi Otac, i ja živim po Ocu, tako i tko mene jede, živjet će po meni. Ovo je kruh, koji je sišao s neba. Ne kao što su jeli vaši oci manu i pomrli, nego tko jede od ovoga kruha, živjet će u vljeke.","knRef":"Kniewald 1942, str. 368–369 (snimka 185) (OCR)"},"c78219a7af7def4d":{"t":"Lev 21, 6\nSvećenici Gospodnji prinose Bogu tamjan i kruh. I zato će biti sveti Bogu svojemu i neće oskvrnuti njegovo ime, <i>aleluja</i>.","kn":"(Levit, 21, 6). Svećenici će Gospodnji prikazivati Bogu kad i hljebove; i zato će biti sveti Bogu svojemu i ne će oskvrnuti njegova imena. Aleluja.","knRef":"Kniewald 1942, str. 368–369 (snimka 185) (OCR)"},"f5fa67582a149314":{"t":"Molimo, Gospodine, umilostivljen podaj svojoj Crkvi darove jedinstva i mira koje prikazani prinosi otajstveno označuju.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>.","kn":"Molimo, Gospodine, milostivo dopusti svojoj Crkvi darove jedinstva i mira, koji su u ovoj žrtvi otajstveno označeni kruhom i vinom. Po G. n. I. K.","knRef":"Kniewald 1942, str. 368–369 (snimka 185) (OCR)"},"404159d2e4df1ef4":{"t":"Uistinu je dostojno i pravedno, pravo i spasonosno, da vazda i svagdje zahvaljujemo tebi, Gospodine, sveti Oče, svemogući vječni Bože, po Kristu Gospodinu našemu. – Po njemu tvoje veličanstvo hvale anđeli, klanjaju se gospodstva i dršću vlasti. Nebesa i nebeske sile i blaženi serafini zajedničkim klicanjem slave. Daj, molimo, s njima i naše glase primi dok govorimo poniznim hvalospjevom:","kn":"Uistinu je dostojno i pravedno, pravo i spasonosno, da vazda i svagdje zahvaljujemo Tebi, Gospodine sveti. Oče svemogući, vječni Bože, po Kristu, Gospotdiniu našemu, po kome veličanstvo Tvoje hvale anđeli, klanjaju Ti se gospodstva, tresu se vlasti. Nebesa Te i nebeske moći i blaženi serafini, zadružnim klicanjem zajedno slave. Zapovijedi, molimo, da se i naši glasovi združe s njihovima, smjernim isippvijedanjem govoreći:","knRef":"Kniewald 1942, str. 18–19 (snimka 10) (OCR)"},"4a5ac84b87f2fe09":{"t":"1 Kor 11, 26-27\nSvaki put, kad jedete ovaj kruh i pijete iz ove čaše, navješćujete smrt Gospodnju, dok on ne dođe. Zato će svaki koji bude nedostojno jeo ovaj kruh ili pio iz Gospodnje čaše, biti krivac tijela i krvi Gospodnje, <i>aleluja</i>.","kn":"(I. Kor. 11, 26). Kadgod budete jeli kruh ovaj i pili kalež ovaj: smrt Gospodnju navještajte, dok ne dođe. Dakle, kojigod bude nedostojno jeo kruh ovaj ili pio kalež Gospodnji, bit će kriv tijelu i krvi Gospodnjoj. Aleluja.","knRef":"Kniewald 1942, str. 368–369 (snimka 185) (OCR)"},"92e37a515ae287b5":{"t":"<i>Pomolimo se</i>.\nDaj molimo, Gospodine, da nas vječno zasiti uživanje tvojega božanstva, koje nam se predočuje vremenitim primanjem tvoga dragocjenog tijela i krvi:\n<i>koji živiš i kraljuješ s Bogom Ocem u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>.","kn":"Učini, molimo, Gospodine, da se napunimo vječnim uživanjem Tvojega Božanstva, što ga predoznačuje vremenito primanje dragocjenoga tijela i krvi Tvoje, koji živiš i kraljuješ . . .","knRef":"Kniewald 1942, str. 368–369 (snimka 185) (OCR)"}}});
